// RESPONSIBILITY: Defines runtime validation schemas for attendance_dashboard; it does not determine server-owned business rules without a verified contract.
// DATA FLOW: API/form boundary → Zod schema → validated typed data or field-level errors → owning hook/view (admin_attendance/attendance_dashboard/schemas/AdminAttendanceDashboardSchemas.ts)

// Generated by ts-to-zod
import { z } from "zod";

export const statusSchema = z.union([z.literal("idle"), z.literal("loading"), z.literal("success"), z.literal("error")]);

export const attendanceStatusSchema = z.union([z.literal("present"), z.literal("absent"), z.literal("late")]);

export const dateRangeFilterSchema = z.union([z.literal("today"), z.literal("yesterday"), z.literal("this_week"), z.literal("this_month"), z.literal("last_month")]);

// Source fixtures and the API-facing record contract use ISO timestamps with an
// explicit timezone. Reject display-only strings at this boundary.
const attendanceTimeSchema = z.string().datetime({ offset: true });

export const adminAttendanceRecordSchema = z.object({
    id: z.string(),
    memberId: z.string(),
    memberName: z.string(),
    memberPhone: z.string(),
    branchId: z.string(),
    branchName: z.string(),
    checkInTime: attendanceTimeSchema,
    checkOutTime: attendanceTimeSchema.nullable(),
    date: z.string(),
    status: attendanceStatusSchema,
    planName: z.string(),
    trainerId: z.string().optional(),
    trainerName: z.string().optional(),
    sessionType: z.union([z.literal("General"), z.literal("PT"), z.literal("Class")]).optional()
});

export const adminAttendanceSummarySchema = z.object({
    todayTotal: z.number().int().nonnegative(),
    todayPresent: z.number().int().nonnegative(),
    todayLate: z.number().int().nonnegative(),
    weeklyAverage: z.number().nonnegative(),
    peakHour: z.string(),
    trendVsLastWeek: z.number(),
    uniqueMembersThisMonth: z.number().int().nonnegative()
});

export const adminAttendanceTrendPointSchema = z.object({
    date: z.string(),
    count: z.number().int().nonnegative()
});
